// Layer 1 — Data upload. PWA drag-drops a bank export (OFX/QFX/CSV);
// workflow parses inline and returns transactions in the standard shape.
// Per data-dump-to-matched-services spec session note (2026-05-28):
// session-only state, NEVER persists, gone when user closes the tab.
//
// This is the seed-data-as-aspiration principle made literal — the user's
// own data becomes the seed shown in our lens.
//
// POST body shape (PWA sends one of these):
//   { format: 'qfx'|'ofx'|'csv'|'auto', content: '<file-text-or-base64>', filename?: 'name.qfx' }
// Content is the file content as text (PWA reads with FileReader.readAsText
// for text files, sends base64 for binary if ever needed).
//
// Returns:
//   { ok, format_detected, transactions: [{id, date, amount, description, type, raw}], summary }

const input = $input.first().json || {};
const body = (input.body && typeof input.body === 'object') ? input.body : input;

let content = (body.content || '').toString();
let format = (body.format || 'auto').toString().toLowerCase();
const filename = (body.filename || '').toString();

if (!content || content.length < 10) {
  return [{ json: { ok: false, error: 'empty or trivially small upload' } }];
}

// If base64-encoded (no obvious text markers), decode.
if (/^[A-Za-z0-9+/=\s]+$/.test(content) && content.length > 200 && !content.includes('<') && !content.includes(',')) {
  try { content = Buffer.from(content, 'base64').toString('utf8'); } catch (_) {}
}

// Auto-detect format if not specified.
if (format === 'auto') {
  if (/<OFX>/i.test(content) || /OFXHEADER/i.test(content) || /<STMTTRN>/i.test(content)) format = 'ofx';
  else if (/^[\s\S]{0,100}(Date|Transaction Date|Posting Date|Posted Date)/i.test(content) && content.includes(',')) format = 'csv';
  else if (filename.toLowerCase().endsWith('.qfx')) format = 'qfx';
  else if (filename.toLowerCase().endsWith('.ofx')) format = 'ofx';
  else if (filename.toLowerCase().endsWith('.csv')) format = 'csv';
  else format = 'csv'; // last-resort guess
}

function parseOfx(text) {
  // Tolerant OFX/QFX parser. Handles SGML-style (unclosed tags) and XML-style.
  const txns = [];
  const tranBlocks = text.split(/<STMTTRN>/i).slice(1);
  for (const block of tranBlocks) {
    const blockEnd = block.search(/<\/STMTTRN>|<STMTTRN>/i);
    const inner = blockEnd >= 0 ? block.slice(0, blockEnd) : block;
    function pick(tag) {
      const re = new RegExp('<' + tag + '>([^<\r\n]+)', 'i');
      const m = inner.match(re);
      return m ? m[1].trim() : '';
    }
    const dt = pick('DTPOSTED').replace(/\[.*$/, '').slice(0, 14);
    const amt = pick('TRNAMT');
    const fitid = pick('FITID');
    const name = pick('NAME');
    const memo = pick('MEMO');
    const trntype = pick('TRNTYPE');
    if (!dt && !amt) continue;
    const yyyy = dt.slice(0, 4), mm = dt.slice(4, 6), dd = dt.slice(6, 8);
    const isoDate = (yyyy && mm && dd) ? (yyyy + '-' + mm + '-' + dd) : '';
    txns.push({
      id: fitid || ('ofx-' + Math.random().toString(36).slice(2, 10)),
      date: isoDate,
      amount: parseFloat(amt) || 0,
      description: [name, memo].filter(Boolean).join(' - ').slice(0, 300),
      type: trntype || '',
      raw: { fitid, dt, amt, name, memo, trntype }
    });
  }
  return txns;
}

function parseCsv(text) {
  // Pragmatic CSV parser. Handles quoted fields with commas. Detects header row.
  const lines = text.split(/\r?\n/).filter(l => l.trim().length > 0);
  if (lines.length < 2) return [];
  function splitRow(row) {
    const out = []; let cur = ''; let inQ = false;
    for (let i = 0; i < row.length; i++) {
      const ch = row[i];
      if (ch === '"') { if (inQ && row[i + 1] === '"') { cur += '"'; i++; } else { inQ = !inQ; } }
      else if (ch === ',' && !inQ) { out.push(cur); cur = ''; }
      else cur += ch;
    }
    out.push(cur);
    return out.map(s => s.trim());
  }
  const header = splitRow(lines[0]).map(h => h.toLowerCase());
  const dateIdx = header.findIndex(h => /^(date|trans|posting|posted|transaction date|trans date|post date)/i.test(h));
  const descIdx = header.findIndex(h => /^(description|memo|payee|name|details|merchant)/i.test(h));
  const amtIdx = header.findIndex(h => /^(amount|debit|credit|amt)/i.test(h));
  // Some banks split debit/credit into separate columns.
  const debitIdx = header.findIndex(h => /^debit$/i.test(h));
  const creditIdx = header.findIndex(h => /^credit$/i.test(h));
  const catIdx = header.findIndex(h => /^(category|type)/i.test(h));
  if (dateIdx < 0 || descIdx < 0) return [];
  const txns = [];
  for (let i = 1; i < lines.length; i++) {
    const cells = splitRow(lines[i]);
    if (cells.length < Math.max(dateIdx, descIdx) + 1) continue;
    const rawDate = cells[dateIdx] || '';
    // Normalize date: handle MM/DD/YYYY and YYYY-MM-DD.
    let isoDate = rawDate;
    const mdY = rawDate.match(/^(\d{1,2})[\/-](\d{1,2})[\/-](\d{2,4})$/);
    if (mdY) {
      let y = mdY[3]; if (y.length === 2) y = '20' + y;
      isoDate = y + '-' + mdY[1].padStart(2, '0') + '-' + mdY[2].padStart(2, '0');
    }
    let amount = 0;
    if (amtIdx >= 0) amount = parseFloat((cells[amtIdx] || '0').replace(/[$,\s]/g, '')) || 0;
    else if (debitIdx >= 0 || creditIdx >= 0) {
      const d = parseFloat((cells[debitIdx] || '0').replace(/[$,\s]/g, '')) || 0;
      const c = parseFloat((cells[creditIdx] || '0').replace(/[$,\s]/g, '')) || 0;
      amount = c - d;
    }
    txns.push({
      id: 'csv-' + i + '-' + Math.random().toString(36).slice(2, 8),
      date: isoDate,
      amount: amount,
      description: (cells[descIdx] || '').slice(0, 300),
      type: catIdx >= 0 ? (cells[catIdx] || '') : '',
      raw: { row: i, cells }
    });
  }
  return txns;
}

let transactions = [];
try {
  if (format === 'ofx' || format === 'qfx') transactions = parseOfx(content);
  else if (format === 'csv') transactions = parseCsv(content);
  else return [{ json: { ok: false, error: 'unsupported format: ' + format } }];
} catch (e) {
  return [{ json: { ok: false, error: 'parse error: ' + String(e), format_detected: format } }];
}

if (transactions.length === 0) {
  return [{ json: { ok: false, error: 'no transactions parsed - file shape may be unrecognized', format_detected: format } }];
}

// Sort by date ascending. Compute simple summary stats.
transactions.sort((a, b) => (a.date || '').localeCompare(b.date || ''));
const total = transactions.reduce((s, t) => s + (t.amount || 0), 0);
const credits = transactions.filter(t => (t.amount || 0) > 0);
const debits = transactions.filter(t => (t.amount || 0) < 0);
const summary = {
  transaction_count: transactions.length,
  date_range: transactions.length ? (transactions[0].date + ' to ' + transactions[transactions.length - 1].date) : '',
  credits_count: credits.length,
  credits_total: credits.reduce((s, t) => s + t.amount, 0),
  debits_count: debits.length,
  debits_total: debits.reduce((s, t) => s + t.amount, 0),
  net: total
};

return [{ json: { ok: true, format_detected: format, summary, transactions } }];
